@php
    $preservedFilters = collect($filters)->except('control_id')->reject(fn ($value) => $value === null || $value === '')
        ->reject(fn ($value, $key) => ($key === 'lifecycle' && $value === 'active') || ($key === 'sort' && $value === 'risk') || ($key === 'per_page' && (int) $value === 25))->all();
    $controlUrl = fn ($control) => route('budget.me.rebuild.data-governance', array_merge($preservedFilters, ['control_id' => $control->id])).'#governance-detail';
    $initials = function ($name) {
        return str(collect(preg_split('/\s+/', trim((string) $name)))->filter()->take(2)->map(fn ($part) => mb_substr($part, 0, 1))->join(''))->upper();
    };
    $tone = fn ($value) => match ($value) {
        'approved', 'implemented', 'resolved', 'low', 'scheduled' => 'success',
        'under_review', 'in_progress', 'internal', 'public' => 'info',
        'draft', 'moderate', 'due_soon', 'risk_accepted', 'not_started' => 'warning',
        'critical', 'high', 'overdue', 'open', 'restricted' => 'danger',
        default => 'neutral',
    };
    $selectedReviewState = $selectedControl?->reviewState();
    $oldContext = old('form_context');
    $oldAction = $selectedControl?->actions?->firstWhere('id', old('action_id'));
