<script src="{{ asset('admin/assets/vendors/js/apexcharts.min.js') }}"></script>
<script>
(function () {
    const ready = function () {
        const body = document.body;
        const openModal = function (id) { const modal = document.getElementById(id); if (!modal) return; document.querySelectorAll('[data-dg-modal].is-open').forEach(item => item.classList.remove('is-open')); modal.classList.add('is-open'); body.classList.add('dg-modal-open'); setTimeout(() => modal.querySelector('input:not([type="hidden"]),select,textarea,button')?.focus(), 20); };
        const closeModal = function (modal) { modal?.classList.remove('is-open'); if (!document.querySelector('[data-dg-modal].is-open')) body.classList.remove('dg-modal-open'); };
        document.addEventListener('click', function (event) {
            const opener = event.target.closest('[data-dg-open]'); if (opener) { event.preventDefault(); openModal(opener.dataset.dgOpen); return; }
            const closer = event.target.closest('[data-dg-close]'); if (closer) { event.preventDefault(); closeModal(closer.closest('[data-dg-modal]')); return; }
            const row = event.target.closest('[data-dg-row]'); if (row && !event.target.closest('a,button,input,select,textarea,form')) { window.location.href = row.dataset.href; return; }
            const edit = event.target.closest('[data-action-edit]'); if (edit) { const form = document.querySelector('[data-action-edit-form]'); form.action = edit.dataset.url; form.querySelector('[name="action_id"]').value = edit.closest('article')?.dataset.actionId || edit.dataset.actionId || ''; form.querySelector('[name="action_type"]').value = edit.dataset.type; form.querySelector('[name="title"]').value = edit.dataset.title; form.querySelector('[name="description"]').value = edit.dataset.description || ''; form.querySelector('[name="priority"]').value = edit.dataset.priority; form.querySelector('[name="status"]').value = edit.dataset.status; form.querySelector('[name="owner_user_id"]').value = edit.dataset.owner || ''; form.querySelector('[name="due_date"]').value = edit.dataset.due || ''; openModal('governance-action-edit'); return; }
            const resolve = event.target.closest('[data-action-resolve]'); if (resolve) { const form = document.querySelector('[data-action-resolve-form]'); form.action = resolve.dataset.url; form.querySelector('[name="action_id"]').value = resolve.dataset.actionId || ''; document.querySelector('[data-resolve-copy]').textContent = 'Record the outcome for “' + resolve.dataset.title + '”. This entry remains in the audit history.'; openModal('governance-action-resolve'); }
        });
        document.addEventListener('keydown', event => { if (event.key === 'Escape') closeModal(document.querySelector('[data-dg-modal].is-open')); });
        document.querySelectorAll('[data-dg-modal][data-auto-open]').forEach(modal => openModal(modal.id));
        if (window.location.hash === '#governance-add') openModal('governance-add');
        document.querySelectorAll('[data-confirm]').forEach(form => form.addEventListener('submit', function (event) { if (!window.confirm(this.dataset.confirm)) event.preventDefault(); }));
        document.querySelectorAll('[data-scope-select]').forEach(select => { const sync = function () { const form = select.closest('form'); form.querySelectorAll('[data-scope-field]').forEach(field => field.hidden = !field.dataset.scopeField.split(',').includes(select.value)); }; select.addEventListener('change', sync); sync(); });

        const lifecycle = @json($charts['lifecycle']); const domains = @json($charts['domain']); const risk = @json($charts['risk']);
        const baseUrl = @json(route('budget.me.rebuild.data-governance')); const baseFilters = @json($preservedFilters);
        const openFiltered = extra => { const query = new URLSearchParams({...baseFilters, ...extra}); window.location.href = baseUrl + '?' + query.toString(); };
        const render = function (selector, options) { const target = document.querySelector(selector); if (!target) return; if (typeof window.ApexCharts !== 'function') { target.innerHTML = '<div class="dg-chart-empty"><strong>Chart unavailable</strong><span>The register and exports remain available.</span></div>'; return; } new window.ApexCharts(target, options).render(); };
        const base = {chart:{fontFamily:'Inter, Arial, sans-serif',foreColor:'#657980',toolbar:{show:false},animations:{speed:380}},grid:{borderColor:'#e4ecee',strokeDashArray:3},tooltip:{theme:'light'},noData:{text:'No governance data in this scope'}};
        render('#dg-lifecycle-chart',{...base,chart:{...base.chart,type:'donut',height:300,events:{dataPointSelection:(_e,_c,s)=>{const item=lifecycle[s.dataPointIndex];if(item)openFiltered({status:item.key,lifecycle:'all'});}}},series:lifecycle.map(i=>i.count),labels:lifecycle.map(i=>i.label),colors:lifecycle.map(i=>i.color),stroke:{colors:['#fff'],width:3},dataLabels:{enabled:false},legend:{position:'bottom',fontSize:'10px'},plotOptions:{pie:{donut:{size:'66%',labels:{show:true,total:{show:true,label:'Instruments',formatter:()=>lifecycle.reduce((sum,i)=>sum+i.count,0)}}}}}});
        render('#dg-domain-chart',{...base,chart:{...base.chart,type:'bar',height:300,events:{dataPointSelection:(_e,_c,s)=>{const item=domains[s.dataPointIndex];if(item)openFiltered({domain:item.key});}}},series:[{name:'Registered',data:domains.map(i=>i.controls)},{name:'Implemented',data:domains.map(i=>i.implemented)}],colors:['#8fb7c2','#187459'],plotOptions:{bar:{horizontal:true,borderRadius:3,barHeight:'58%'}},xaxis:{categories:domains.map(i=>i.label),min:0,forceNiceScale:true,labels:{formatter:v=>Math.round(v)}},yaxis:{labels:{maxWidth:180,style:{fontSize:'9px'}}},dataLabels:{enabled:false},legend:{position:'bottom',fontSize:'10px'}});
        render('#dg-risk-chart',{...base,chart:{...base.chart,type:'bar',height:300,events:{dataPointSelection:(_e,_c,s)=>{const item=risk[s.dataPointIndex];if(item)openFiltered({risk:item.key});}}},series:[{name:'Instruments',data:risk.map(i=>i.count)}],colors:risk.map(i=>i.color),plotOptions:{bar:{distributed:true,borderRadius:4,columnWidth:'52%'}},xaxis:{categories:risk.map(i=>i.label)},yaxis:{min:0,forceNiceScale:true,labels:{formatter:v=>Math.round(v)}},dataLabels:{enabled:true,formatter:v=>Math.round(v)},legend:{show:false}});
    };
    if (document.readyState === 'loading') document.addEventListener('DOMContentLoaded', ready, {once:true}); else ready();
})();
</script>
